using CompassNavigatorPro;using LWS.TruckSports;using UnityEngine;
namespace LWS.TruckSubmarine {
 // Semantic target selection only. Existing CNP owns arrows, projection,
 // viewport edges, typography and indicator animation.
 [DefaultExecutionOrder(920)]public sealed class SubmarineSonarGuidance:MonoBehaviour {
  public SubmarineMatch match;public SportsBroadcastCompass[] compasses;public CompassProPOI[] markers;
  void LateUpdate(){if(match==null)return;for(int i=0;i<5;i++){bool active=match.Live&&(i==4?match.drivingViews.NeedsArena:!match.drivingViews.NeedsArena&&i<match.drivingViews.rally.Humans);var compass=compasses[i];var marker=markers[i];int slot=i==4?SharedOwner():active?match.drivingViews.rally.owners[i]:-1;var target=slot>=0?Target(slot):null;active&=slot>=0&&(target!=null||match.divers[slot].Carrying!=null);if(compass.gameObject.activeSelf!=active)compass.gameObject.SetActive(active);if(marker.gameObject.activeSelf!=active)marker.gameObject.SetActive(active);if(!active)continue;var diver=match.divers[slot];var camera=i==4?match.broadcast.view:match.cameras[i];compass.cameraMain=camera;compass.follow=diver.truck.transform;compass.viewportRect=camera.rect;var canvas=compass.GetComponent<Canvas>();if(canvas!=null)canvas.worldCamera=camera;bool carrying=diver.Carrying!=null;marker.transform.position=carrying?match.buoy.transform.position:target.body.position;float distance=Vector3.Distance(diver.truck.body.position,marker.transform.position);marker.title=(carrying?"DELIVER":target.kind.ToString().ToUpperInvariant())+" · "+Mathf.RoundToInt(distance)+"m · "+Mathf.RoundToInt(-marker.transform.position.y)+"m DEPTH";marker.tintColor=carrying?new Color(1,.8f,.15f):new Color(.1f,.9f,1);if(!compass.POIisRegistered(marker))compass.POIRegister(marker);}}
  int SharedOwner(){var framing=match.broadcast.GetComponent<SportsBroadcastFraming>();if(framing!=null&&framing.Primary>=0&&framing.Primary<match.setup.count)return framing.Primary;return match.LastDeliveredOwner>=0?match.LastDeliveredOwner:0;}
  SubmarineCargo Target(int slot){SubmarineCargo nearest=null;float best=float.MaxValue;var d=match.divers[slot];foreach(var cargo in match.treasures){if(!d.discovered[cargo.id]||!match.rules.Available(cargo.id))continue;float cost=(cargo.body.position-d.truck.body.position).sqrMagnitude;if(cost<best){best=cost;nearest=cargo;}}return nearest;}
  void OnDisable(){if(markers!=null)foreach(var marker in markers)if(marker!=null)marker.gameObject.SetActive(false);if(compasses!=null)foreach(var compass in compasses)if(compass!=null)compass.gameObject.SetActive(false);}
 }
}
